import { spawnSync } from "node:child_process";
import { pathToFileURL } from "node:url";

export function assertVisualUpdateEnvironment({
  platform = process.platform,
  githubActions = process.env.GITHUB_ACTIONS,
  refreshAuthorized = process.env.FCR_VISUAL_REFRESH,
} = {}) {
  if (
    platform === "linux"
    && !(githubActions === "true" && refreshAuthorized === "1")
  ) {
    throw new Error(
      "Linux visual baselines may only be regenerated by the "
      + "Visual baseline refresh GitHub Actions workflow. Dispatch "
      + "visual-refresh.yml for this branch and use its artifact.",
    );
  }
}

export function runVisualUpdate({ spawn = spawnSync } = {}) {
  assertVisualUpdateEnvironment();
  const result = spawn(
    "pnpm",
    ["exec", "playwright", "test", "--update-snapshots"],
    { stdio: "inherit" },
  );
  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error(`Visual snapshot update failed with exit code ${result.status}`);
  }
}

if (
  process.argv[1]
  && import.meta.url === pathToFileURL(process.argv[1]).href
) {
  try {
    runVisualUpdate();
  } catch (error) {
    console.error(error instanceof Error ? error.message : "Visual snapshot update failed");
    process.exitCode = 1;
  }
}
